window.AUTH=window.AUTH||{};window.AUTH["21-806"]={"d":"21-806","id":"2022/21-806","n":"Health and Hospital Corporation of Marion County v. Talevski","briefs":[{"k":"petitioner","label":"Brief of petitioners Health and Hospital Corporation of Marion County, et al.","date":"2022-07-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/230306/20220718175856195_2022-07-18%20Final%20Brief%20HHC%20v.%20Talevski%20PDF-A.pdf","side":"pet","n":133},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2022-07-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/230817/20220725195544307_21-806%20-%20US%20Amicus%20Br%20-%20Talevski%20FINAL.pdf","side":"us","n":114},{"k":"respondent","label":"Brief of respondent Ivanka Talevski, Personal Representative of the Estate of Gorgi Talevski, Deceased","date":"2022-09-16","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/238112/20220916160554873_Talevski%20Brief%20and%20App%20-%2021-806.pdf","side":"res","n":127},{"k":"reply","label":"Reply of petitioners Health and Hospital Corporation of Marion County, et al.","date":"2022-10-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/243267/20221017144551803_21-806%20Brief.pdf","side":"pet","n":63}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r36_feah.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":6,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"passim","3":"21, 22"}},{"t":"case","label":"Allen & Currey Mfg. Co. v. Shreveport Waterworks Co.","cite":"37 So. 980","y":1905,"court":"La.","url":"https://www.courtlistener.com/c/So./37/980/","by":{"0":"19"}},{"t":"case","label":"Anderson v. Ghaly","cite":"930 F.3d 1066","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/1066/","by":{"0":"43","2":"39, 40"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"op":2,"ar":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"3, 11, 30","1":"17","2":"12","3":"8, 9, 12"}},{"t":"case","label":"Beck v. Kittanning Water Co.","cite":"11 A. 300","y":1887,"court":"Pa.","url":"https://www.courtlistener.com/c/A./11/300/","by":{"0":"19"}},{"t":"case","label":"Blessing v. Freestone","cite":"520 U.S. 329","y":1997,"id":"1996/95-1441","sc":1,"op":2,"ar":9,"sum":"The Court ruled that Title IV-D of the Social Security Act does not give individuals a federal right to force a state agency to substantially comply with Title IV-D. Justice O'Connor wrote for the court that parents cannot sue merely because a state fails to be in \"substantial compliance\" with federal collection standards.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim, 21","3":"5, 12, 15, 22"}},{"t":"case","label":"Blymire v. Boistle","cite":"6 Watts 182","y":1837,"court":"Pa.","url":"https://www.courtlistener.com/c/Watts/6/182/","by":{"0":"16"}},{"t":"case","label":"Buckley v. Fitzsimmons","cite":"509 U.S. 259","y":1993,"id":"1992/91-7849","sc":1,"sum":"Petitioner Buckley sought damages, under 42 U. S. C. § 1983, from respondent prosecutors for fabricating evidence during the preliminary investigation of a highly publicized rape and murder in Illinois and making false statements at a press conference announcing the return of an indictment against him. He claimed that when three separate lab studies failed to make a reliable connection between a bootprint at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Butterfield v. Hartshorn","cite":"7 N.H. 345","y":1834,"url":"https://www.courtlistener.com/c/N.H./7/345/","by":{"0":"15"}},{"t":"case","label":"Cal. Ass’n of Rural Health Clinics v. Douglas","cite":"738 F.3d 1007","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/1007/","by":{"0":"33"}},{"t":"case","label":"Cannon v. Univ. of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"op":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","3":"14"}},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"op":1,"sum":"The Court held that the purpose of the Civil Rights Act of 1871 is to compensate people for injuries caused by the deprivation of civil rights, which means that compensation cannot occur without proof of injury. However, the definition of injury must be adapted to fit the civil rights in question.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Chamberlain v. New Hampshire Fire Ins. Co.","cite":"55 N.H. 249","y":1875,"url":"https://www.courtlistener.com/c/N.H./55/249/","by":{"0":"15"}},{"t":"case","label":"City of Brooklyn v. Brooklyn City R.R. Co.","cite":"47 N.Y. 475","y":1872,"url":"https://www.courtlistener.com/c/N.Y./47/475/","sum":"Noting that, under state act that authorized contract, defendant was vested “with the power to bring suits in behalf of the State” and with police power to “to seize and detain all boats”.","sumSrc":"brief:3","by":{"0":"20","1":"19, 20","3":"9"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"op":26,"ar":7,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"0":"41, 42","1":"28","2":"40, 43","3":"15, 17, 23"}},{"t":"case","label":"Conklin v. Smith","cite":"7 Ind. 107","y":1855,"url":"https://www.courtlistener.com/c/Ind./7/107/","by":{"0":"16"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"142 S. Ct. 1562","y":2022,"id":"2021/20-219","sc":1,"op":1,"ar":2,"sum":"Emotional distress damages are not recoverable in a private action to enforce either the Rehabilitation Act of 1973 or the Affordable Care Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"13, 23","1":"17","3":"3"}},{"t":"case","label":"DaimlerChrysler v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Davis v. Clinton Water-Works Co.","cite":"6 N.W. 126","y":1880,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W./6/126/","by":{"0":"19, 20"}},{"t":"case","label":"DeCambre v. Brookline Hous. Auth.","cite":"826 F.3d 1","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/826/1/","by":{"0":"32"}},{"t":"case","label":"Doremus v. Board of Educ.","cite":"342 U.S. 429","y":1952,"id":"scdb/1951-047","sc":1,"sum":"The appeal is dismissed for want of jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Dow v. Clark","cite":"73 Mass. 198","y":1856,"url":"https://www.courtlistener.com/c/Mass./73/198/","by":{"0":"16"}},{"t":"case","label":"Eaton v. Fairbury Waterworks Co.","cite":"56 N.W. 201","y":1893,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./56/201/","by":{"0":"19"}},{"t":"case","label":"Egbert v. Boule","cite":"142 S. Ct. 1793","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 27, 29","3":"4"}},{"t":"case","label":"Empire State Ins. Co. v. Collins","cite":"54 Ga. 376","y":1875,"url":"https://www.courtlistener.com/c/Ga./54/376/","by":{"0":"16"}},{"t":"case","label":"Ferris v. Carson Water Co.","cite":"16 Nev. 44","y":1881,"url":"https://www.courtlistener.com/c/Nev./16/44/","by":{"0":"19"}},{"t":"case","label":"Fitzgerald v. Barnstable Sch. Comm.","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"op":11,"ar":4,"sum":"The Court found that a claim filed under Title IX for violation of the Equal Protection Clause of the fourteenth Amendment does not preclude the use of 42 U.S.C. Section 1983 which protects against the deprivation of any rights guaranteed by the Constitution and federal law.","sumSrc":"Oyez","by":{"0":"41","1":"28, 32","2":"39, 40, 41","3":"15, 17, 18"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"Fowler v. Athens Water-Works Co.","cite":"9 S.E. 673","y":1889,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./9/673/","by":{"0":"19"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"Fugure v. Mut. Soc’y of St. Joseph","cite":"46 Vt. 362","y":1874,"url":"https://www.courtlistener.com/c/Vt./46/362/","by":{"0":"16"}},{"t":"case","label":"Gee v. Planned Parenthood of Gulf Coast, Inc.","cite":"139 S. Ct. 408","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./139/408/","sc":1,"by":{"0":"33","3":"3, 4"}},{"t":"case","label":"Gonzaga Univ. v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"op":28,"ar":20,"sum":"The Court held that such an action is foreclosed because the relevant provisions of FERPA create no personal rights to enforce.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim, 21","3":"passim"}},{"t":"case","label":"Grammer v. John J. Kane Reg’l Ctrs.Glen Hazel","cite":"570 F.3d 520","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/570/520/","by":{"0":"43, 44"}},{"t":"case","label":"Gunter v. Mooney","cite":"72 Ga. 205","y":1883,"url":"https://www.courtlistener.com/c/Ga./72/205/","by":{"0":"16"}},{"t":"case","label":"H.R. Mock v. Rensselaer Water Co.","cite":"247 N.Y. 160","y":1928,"url":"https://www.courtlistener.com/c/N.Y./247/160/","by":{"0":"22"}},{"t":"case","label":"Hall v. Huntoon","cite":"17 Vt. 244","y":1845,"url":"https://www.courtlistener.com/c/Vt./17/244/","by":{"0":"16"}},{"t":"case","label":"Hernández v. Mesa","cite":"140 S. Ct. 735","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"0":"24, 29","3":"12"}},{"t":"case","label":"House v. Houston Waterworks Co.","cite":"31 S.W. 179","y":1895,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W./31/179/","op":3,"by":{"0":"19"}},{"t":"case","label":"Howsmon v. Trenton Water Co.","cite":"24 S.W. 784","y":1893,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./24/784/","by":{"0":"19"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"sum":"Respondent, stockholder of petitioner company, brought a civil action in federal court for deprivation of his and other stockholders' preemptive rights by reason of a merger involving the company, allegedly effected through use of a false and misleading proxy statement. The complaint has two counts, one based on diversity and claiming a breach of directors' fiduciary duty to stockholders and the other alleging a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 27"}},{"t":"case","label":"Jefferson v. Asch","cite":"55 N.W. 604","y":1893,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./55/604/","by":{"0":"16"}},{"t":"case","label":"Jones v. Thomas","cite":"62 Va. 96","y":1871,"url":"https://www.courtlistener.com/c/Va./62/96/","by":{"0":"16"}},{"t":"case","label":"Kalina v. Fletcher","cite":"522 U.S. 118","y":1997,"id":"1997/96-792","sc":1,"sum":"The Court held that section 1983 may create a damages remedy against a prosecutor for making false statements of fact in an affidavit supporting an application for an arrest warrant, since such conduct is not protected by the doctrine of absolute prosecutorial immunity.","sumSrc":"Oyez","by":{"0":"12","1":"18","2":"27, 28","3":"4"}},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"142 S. Ct. 2407","y":2022,"id":"2021/21-418","sc":1,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Kimble v. Mavel Ent., LLC","cite":"576 U.S. 446","y":2015,"url":"https://supreme.justia.com/cases/federal/us/576/446/","sc":1,"by":{"0":"31, 36"}},{"t":"case","label":"Kulwicki v. Munro","cite":"54 N.W. 703","y":1893,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./54/703/","by":{"0":"20"}},{"t":"case","label":"La Mourea v. Rhude","cite":"295 N.W. 304","y":1940,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./295/304/","by":{"0":"21"}},{"t":"case","label":"Lawrence v. Fox","cite":"20 N.Y. 268","y":1859,"url":"https://www.courtlistener.com/c/N.Y./20/268/","by":{"0":"16, 17"}},{"t":"case","label":"Leegin Creative Leather Prods., Inc. v. PSKS, Inc.","cite":"551 U.S. 877","y":2007,"id":"2006/06-480","sc":1,"sum":"The Court ruled 5-4 that \" Dr. Miles should be overruled and that vertical price restraints are to be judged by the rule of reason.\" Justice Anthony Kennedy's majority opinion held that Dr. Miles had erred by treating vertical minimum price agreements between manufacturers and retailers as analogous to horizontal price-fixing agreements between sellers.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Maine v. Thiboutot","cite":"448 U.S. 1","y":1980,"id":"1979/79-838","sc":1,"op":12,"sum":"Observing that our cases, running back to at least Page 1968, only mPakreoseonsfe Pif “elawnsd” inindeged mPeaunsb“llaiwcsa”.","sumSrc":"opinion","by":{"0":"2","1":"7, 10, 11, 29","2":"1, 8, 9, 21, 23, 24","3":"12"}},{"t":"case","label":"McCarteney v. Wyoming Nat’l Bank","cite":"1 Wyo. 382","y":1877,"url":"https://www.courtlistener.com/c/Wyo./1/382/","by":{"0":"16"}},{"t":"case","label":"McCready v. White","cite":"417 F.3d 700","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/417/700/","by":{"0":"32"}},{"t":"case","label":"McMahon v. Second Ave. R.R. Co.","cite":"75 N.Y. 231","y":1878,"url":"https://www.courtlistener.com/c/N.Y./75/231/","by":{"0":"20"}},{"t":"case","label":"Mellen v. Whipple","cite":"67 Mass. 317","y":1854,"url":"https://www.courtlistener.com/c/Mass./67/317/","by":{"0":"16"}},{"t":"case","label":"Mendez v. Brown","cite":"311 F. Supp. 2d 134","y":2004,"court":"D. Mass","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/311/134/","sum":"Stating that court could not decide whether to apply Blessing or Gonzaga, but nevertheless concluding that there is a private right to enforce § 1396a(a)(17).","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Middlesex Cnty. Sewerage Auth. v. Nat'l Sea Clammers Ass'n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"op":11,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 42","1":"28, 34","2":"40, 43","3":"15, 18, 20, 23"}},{"t":"case","label":"Monell v. Dep’t of Soc. Servs.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"37","2":"25, 26"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"op":20,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"N.Y. State Citizens’ Coal. for Children v. Poole","cite":"922 F.3d 69","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/922/69/","sum":"Observing that “the Supreme Court’s more recent jurisprudence calls into question the vitality of” Blessing.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"Nasello v. Eagleson","cite":"977 F.3d 599","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/599/","by":{"0":"32"}},{"t":"case","label":"Nat’l Bank v. Grand Lodge","cite":"98 U.S. 123","y":1878,"id":"scdb/1878-032","sc":1,"sum":"This is an action by the Second National Bank of Saint Louis, Missouri, against the Grand Lodge of Missouri of Free and Accepted Ancient Masons, to compel the payment of certain coupons formerly attached to bonds issued in June, 1869, by the Masonic Hall Association, a corporation existing under the laws of the State of Missouri, in relation to which bonds the Grand Lodge, Oct. 14, 1869, adopted the following …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":4,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"3, 25","1":"23"}},{"t":"case","label":"Nieves v. Bartlett","cite":"139 S. Ct. 1715","y":2019,"id":"2018/17-1174","sc":1,"op":2,"sum":"Because police officers had probable cause to arrest Bartlett, his First Amendment retaliatory arrest claim fails as a matter of law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"12"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","2":"25"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"op":12,"ar":5,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"15, 16, 26","2":"9, 10, 15, 36","3":"2, 11, 13, 20"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"sum":"Bribery of private employees prohibited by state criminal statutes violates the Travel Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Pharm. Research & Mfrs. of Am. v. Walsh","cite":"538 U.S. 644","y":2003,"id":"2002/01-188","sc":1,"sum":"The Court held, 9-0, that the Pharmaceutical Research and Manufacturers of America had not carried its burden of showing a probability of success on the merits of its Commerce Clause claims and, 6-3, that their showing was insufficient to support a finding that the Medicaid Act pre-empts Maine's Rx Program insofar as it threatens to coerce manufacturers into reducing their prices on non- Medicaid sales.","sumSrc":"Oyez","by":{"0":"3, 10"}},{"t":"case","label":"Pierson v. Ray","cite":"386 U.S. 547","y":1967,"id":"1966/79","sc":1,"sum":"Petitioners,t,'members of a group of white and Negro clergymen on a \"prayer pilgrimage\" to promote racial integration, attempted to use a segregated interstate bus terminal waiting room in Jackson, Mississippi, in 1961. They were arrested by respondent policemen and charged with conduct breaching the peace in violation of § 2087.5 of the Mississippi Code which this Court, in 1965, held unconstitutional in Thomas v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Pipp v. Reynolds","cite":"20 Mich. 88","y":1870,"url":"https://www.courtlistener.com/c/Mich./20/88/","by":{"0":"16"}},{"t":"case","label":"Planned Parenthood S. Atl. v. Baker","cite":"941 F.3d 687","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/687/","by":{"0":"33"}},{"t":"case","label":"Planned Parenthood S. Atl. v. Kerr","cite":"24 F.4th 945","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/945/","by":{"0":"34"}},{"t":"case","label":"Porter v. Richmond & D.R. Co.","cite":"2 S.E. 374","y":1887,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./2/374/","by":{"0":"20"}},{"t":"case","label":"Rio Grande Cmty. Health Ctr., Inc. v. Rullan","cite":"397 F.3d 56","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/397/56/","sum":"Finding that Gonzaga imposed “somewhat different factors” and applying “Gonzaga rather than the Blessing test”.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/American Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Rogers v. Union Stone Co.","cite":"130 Mass. 581","y":1881,"url":"https://www.courtlistener.com/c/Mass./130/581/","by":{"0":"16"}},{"t":"case","label":"Ross v. Milne","cite":"39 Va. 204","y":1841,"url":"https://www.courtlistener.com/c/Va./39/204/","by":{"0":"15"}},{"t":"case","label":"Schnaier v. Bradley Contracting Co.","cite":"181 A.D. 538","y":1918,"court":"N.Y.","url":"https://www.courtlistener.com/c/A.D./181/538/","ar":2,"by":{"0":"21"}},{"t":"case","label":"South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"op":1,"sum":"The Court ruled that Congress did not exceed its spending powers or violate the Twenty-First Amendment when it conditioned the award of federal highway funds on states' adoption of a uniform minimum drinking age.","sumSrc":"Oyez","by":{"0":"13","3":"2, 3"}},{"t":"case","label":"St. Paul Water Co. v. Ware","cite":"83 U.S. 566","y":1872,"id":"scdb/1872-172","sc":1,"sum":"The city of St. Paul, desiring to have water-pipes laid along the streets of the city, passed an ordinance authorizing the St. Paul Water Company, an incorporated company, so to lay them. But as it was necessary that large excavations of the earth should be.made along the -streets, and considerable blasting of rock, below, the ordinance in one of its sections, the 6th, thus provided:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"State Oil Co. v. Khan","cite":"522 U.S. 3","y":1997,"id":"1997/96-871","sc":1,"sum":"The Court noted that antitrust cases are typically decided by weighing the costs and benefits of restrictions in each individual case instead of by per se rules as in Albrecht . Also, there was significant precedent contradicting the assertion that all trade restrictions are illegal, and there was evidence that the effects of price-fixing are not as detrimental as the Court thought at the time of Albrecht .","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Stuart v. James River & Kanawha Co.","cite":"65 Va. 294","y":1874,"url":"https://www.courtlistener.com/c/Va./65/294/","by":{"0":"16"}},{"t":"case","label":"Styron v. Bell","cite":"53 N.C. 222","y":1860,"url":"https://www.courtlistener.com/c/N.C./53/222/","by":{"0":"16"}},{"t":"case","label":"Suter v. Artist M.","cite":"503 U.S. 347","y":1992,"id":"1991/90-1488","sc":1,"op":1,"ar":1,"sum":"In a 7-to-2 decision, the Supreme Court held that the Adoption Assistance and Child Welfare Act of 1980 only required that a state have a plan for the administration of adoption and foster care programs in order to receive federal reimbursement, not that the plan be correctly carried out.","sumSrc":"Oyez","by":{"0":"29","1":"12, 13","2":"passim, 21","3":"12, 13, 22"}},{"t":"case","label":"Talevski ex rel. Talevski v. Health & Hosp. Corp. of Marion Cnty.","cite":"6 F.4th 713","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/713/","op":1,"by":{"0":"1, 5"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"op":1,"sum":"From the allegations of the complaint, it appears that petitioners were acting in a field where legislators traditionally have power to act; and 8 U. S. C. §§ 43 and 47 (3) do not create civil liability for such conduct.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Turner v. McCarty","cite":"22 Mich. 265","y":1871,"url":"https://www.courtlistener.com/c/Mich./22/265/","by":{"0":"16"}},{"t":"case","label":"Vrooman v. Turner","cite":"69 N.Y. 280","y":1877,"url":"https://www.courtlistener.com/c/N.Y./69/280/","by":{"0":"17"}},{"t":"case","label":"Wainwright v. Queens Cnty. Water Co.","cite":"28 N.Y.S. 987","y":1894,"court":"Gen. Term","url":"https://www.courtlistener.com/c/N.Y.S./28/987/","by":{"0":"19"}},{"t":"case","label":"Warren v. Batchelder","cite":"15 N.H. 129","y":1844,"url":"https://www.courtlistener.com/c/N.H./15/129/","by":{"0":"15"}},{"t":"case","label":"Westside Mothers v. Haveman","cite":"133 F. Supp. 2d 549","y":2001,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/133/549/","op":1,"by":{"0":"17"}},{"t":"case","label":"Wheat v. Rice","cite":"97 N.Y. 296","y":1884,"url":"https://www.courtlistener.com/c/N.Y./97/296/","by":{"0":"17"}},{"t":"case","label":"Wilder v. Virginia Hospital Association","cite":"496 U.S. 498","y":1990,"id":"1989/88-2043","sc":1,"op":1,"ar":4,"sum":"In a 5-to-4 decision, the Court held that the Boren Amendment clearly established a right to reasonable and adequate reimbursement rates for the hospitals.","sumSrc":"Oyez","by":{"0":"passim","1":"11, 12","2":"2, 10, 13, 23, 40, 41, 21","3":"12, 13"}},{"t":"case","label":"Will v. Michigan Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 18, 26","1":"32","3":"4, 5, 11"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Wright v. City of Roanoke Redevelopment & Housing Authority","cite":"479 U.S. 418","y":1987,"id":"1986/85-5915","sc":1,"op":1,"sum":"The Brooke Amendment to the Housing Act of 1937 imposed a ceiling on rents charged to low-income persons living in public housing projects, and, as later amended, provides that a low-income family \"shall pay as rent\" a specified percentage of its income. The Department of Housing and Urban Development (HUD) has consistently considered \"rent\" to include a reasonable amount for the use of utilities. Petitioners, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2","1":"12, 29","2":"10, 13, 23, 40, 41","3":"12"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","subs":["(a)(17)","(a)(13)(A)","(a)","(a)(5)","(a)(8)","(a)(10)(A)","(a)(23)","(b)"],"stext":{"head":"§1396a. State plans for medical assistance","paras":[[0,"(a) Contents"],[0,"A State plan for medical assistance must—"],[1,"(1) provide that it shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(2) provide for financial participation by the State equal to not less than 40 per centum of the non-Federal share of the expenditures under the plan with respect to which payments under section 1396b of this title are authorized by this subchapter; and, effective July 1, 1969, provide for financial participation by the State equal to all of such non-Federal share or provide for distribution of funds from Federal or State sources, for carrying out the State plan, on an equalization or other basis which will assure that the lack of adequate funds from local sources will not result in lowering the amount, duration, scope, or quality of care and services available under the plan;"],[1,"(3) provide for granting an opportunity for a fair hearing before the State agency to any individual whose claim for medical assistance under the plan is denied or is not acted upon with reasonable promptness;"],[1,"(4) provide (A) such methods of administration (including methods relating to the establishment and maintenance of personnel standards on a merit basis, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, and compensation of any individual employed in accordance with such methods, including provision for utilization of professional medical personnel in the administration and, where administered locally, supervision of administration of the plan, and, subject to section 1396b(i) of this title, including a specification that the single State agency described in paragraph (5) will ensure necessary transportation for beneficiaries under the State plan to and from providers and a description of the methods that such agency will use to ensure such transportation) as are found by the Secretary to be necessary for the proper and efficient operation of the plan, (B) for the training and effective use of paid subprofessional staff, with particular emphasis on the full-time or part-time employment of recipients and other persons of low income, as community service aides, in the administration of the plan and for the use of nonpaid or partially paid volunteers in a social service volunteer program in providing services to applicants and recipients and in assisting any advisory committees established by the State agency, (C) that each State or local officer, employee, or independent contractor who is responsible for the expenditure of substantial amounts of funds under the State plan, each individual who formerly was such an officer, employee, or contractor, and each partner of such an officer, employee, or contractor shall be prohibited from committing any act, in relation to any activity under the plan, the commission of which, in connection with any activity concerning the United States Government, by an officer or employee of the United States Government, an individual who was such an officer or employee, or a partner of such an officer or employee is prohibited by section 207 or 208 of title 18, and (D) that each State or local officer, employee, or independent contractor who is responsible for selecting, awarding, or otherwise obtaining items and services under the State plan shall be subject to safeguards against conflicts of interest that are at least as stringent as the safeguards that apply under chapter 21 of title 41 to persons described in section 2102(a)(3) of title 41;"],[1,"(5) either provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan; or provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan, except that the determination of eligibility for medical assistance under the plan shall be made by the State or local agency administering the State plan approved under subchapter I or XVI (insofar as it relates to the aged) if the State is eligible to participate in the State plan program established under subchapter XVI, or by the agency or agencies administering the supplemental security income program established under subchapter XVI or the State plan approved under part A of subchapter IV if the State is not eligible to participate in the State plan program established under subchapter XVI;"],[1,"(6) provide that the State agency will make such reports, in such form and containing such information, as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provide—"],[2,"(A) safeguards which restrict the use or disclosure of information concerning applicants and recipients to purposes directly connected with—"],[3,"(i) the administration of the plan; and"],[3,"(ii) the exchange of information necessary to certify or verify the certification of eligibility of children for free or reduced price breakfasts under the Child Nutrition Act of 1966 [42 U.S.C. 1771 et seq.] and free or reduced price lunches under the Richard B. Russell National School Lunch Act [42 U.S.C. 1751 et seq.], in accordance with section 9(b) of that Act [42 U.S.C. 1758(b)], using data standards and formats established by the State agency; and"],[2,"(B) that, notwithstanding the Express Lane option under subsection (e)(13), the State may enter into an agreement with the State agency administering the school lunch program established under the Richard B. Russell National School Lunch Act under which the State shall establish procedures to ensure that—"],[3,"(i) a child receiving medical assistance under the State plan under this subchapter whose family income does not exceed 133 percent of the poverty line (as defined in section 9902(2) of this title, including any revision required by such section), as determined without regard to any expense, block, or other income disregard, applicable to a family of the size involved, may be certified as eligible for free lunches under the Richard B. Russell National School Lunch Act and free breakfasts under the Child Nutrition Act of 1966 without further application; and"],[3,"(ii) the State agencies responsible for administering the State plan under this subchapter, and for carrying out the school lunch program established under the Richard B. Russell National School Lunch Act (42 U.S.C. 1751 et seq.) or the school breakfast program established by section 4 of the Child Nutrition Act of 1966 (42 U.S.C. 1773), cooperate in carrying out paragraphs (3)(F) and (15) of section 9(b) of that Act [42 U.S.C. 1758(b)];"],[1,"(8) provide that all individuals wishing to make application for medical assistance under the plan shall have opportunity to do so, and that such assistance shall be furnished with reasonable promptness to all eligible individuals;"],[1,"(9) provide—"],[2,"(A) that the State health agency, or other appropriate State medical agency (whichever is utilized by the Secretary for the purpose specified in the first sentence of section 1395aa(a) of this title), shall be responsible for establishing and maintaining health standards for private or public institutions in which recipients of medical assistance under the plan may receive care or services,"],[2,"(B) for the establishment or designation of a State authority or authorities which shall be responsible for establishing and maintaining standards, other than those relating to health, for such institutions,"],[2,"(C) that any laboratory services paid for under such plan must be provided by a laboratory which meets the applicable requirements of section 1395x(e)(9) of this title or paragraphs (16) and (17) of section 1395x(s) of this title, or, in the case of a laboratory which is in a rural health clinic, of section 1395x(aa)(2)(G) of this title, and"],[2,"(D) that the State maintain a consumer-oriented website providing useful information to consumers regarding all skilled nursing facilities and all nursing facilities in the State, including for each facility, Form 2567 State inspection reports (or a successor form), complaint investigation reports, the facility's plan of correction, and such other information that the State or the Secretary considers useful in assisting the public to assess the quality of long term care options and the quality of care provided by individual facilities;"],[1,"(10) provide—"],[2,"(A) for making medical assistance available, including at least the care and services listed in paragraphs (1) through (5), (13)(B), (17), (21), (28), (29), and (30) of section 1396d(a) of this title, to—"],[3,"(i) all individuals—"],[4,"(I) who are receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A or part E of subchapter IV (including individuals eligible under this subchapter by reason of section 602(a)(37),1 606(h),1 or 673(b) of this title, or considered by the State to be receiving such aid as authorized under section 682(e)(6)1 of this title),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396a. State plans for medical assistance","tname":"The Public Health and Welfare","by":{"0":"33, 27","1":"2, 2, 21, 2, 21, 22, 2"}},{"t":"usc","label":"42 U.S.C. § 1396r","url":"https://www.law.cornell.edu/uscode/text/42/1396r","subs":["(c)","(c)(1)(A)(ii)","(c)(1)(A)(vi)","(c)(2)(A)","(c)(2)(A)(i)","(c)(2)(A)(ii)","(c)(2)(A)(iii)","(e)(3)","(g)(2)(A)","(h)(2)(A)(i)","(h)(2)(A)(ii)","(h)(2)(A)(iii)","(h)(2)(A)(iv)","(h)(3)(A)","(h)(3)(B)","(h)(3)(C)","(h)(8)","(c)(1)(A)","(c)(1)(A)(ii)(I)","(c)(2)","(c)(2)(F)","(e)(7)","(g)(1)(A)","(g)(2)","(g)(2)(A)(ii)(III)","(g)(2)(B)","(g)(3)","(g)(4)","(g)(4)(A)","(g)(5)","(h)","(c)(1)(A)(iv)","(c)(1)(B)","(c)(1)(B)(i)","(c)(1)(B)(ii)","(c)(1)(C)","(b)","(d)","(e)","(f)","(g)"],"stext":{"head":"§1396r. Requirements for nursing facilities","paras":[[0,"(a) \"Nursing facility\" defined"],[0,"In this subchapter, the term \"nursing facility\" means an institution (or a distinct part of an institution) which—"],[1,"(1) is primarily engaged in providing to residents—"],[2,"(A) skilled nursing care and related services for residents who require medical or nursing care,"],[2,"(B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons, or"],[2,"(C) on a regular basis, health-related care and services to individuals who because of their mental or physical condition require care and services (above the level of room and board) which can be made available to them only through institutional facilities,"],[1,"and is not primarily for the care and treatment of mental diseases;"],[1,"(2) has in effect a transfer agreement (meeting the requirements of section 1395x(l) of this title) with one or more hospitals having agreements in effect under section 1395cc of this title; and"],[1,"(3) meets the requirements for a nursing facility described in subsections (b), (c), and (d) of this section."],[0,"Such term also includes any facility which is located in a State on an Indian reservation and is certified by the Secretary as meeting the requirements of paragraph (1) and subsections (b), (c), and (d)."],[0,"(b) Requirements relating to provision of services"],[0,"(1) Quality of life"],[0,"(A) In general"],[2,"A nursing facility must care for its residents in such a manner and in such an environment as will promote maintenance or enhancement of the quality of life of each resident."],[0,"(B) Quality assessment and assurance"],[2,"A nursing facility must maintain a quality assessment and assurance committee, consisting of the director of nursing services, a physician designated by the facility, and at least 3 other members of the facility's staff, which (i) meets at least quarterly to identify issues with respect to which quality assessment and assurance activities are necessary and (ii) develops and implements appropriate plans of action to correct identified quality deficiencies. A State or the Secretary may not require disclosure of the records of such committee except insofar as such disclosure is related to the compliance of such committee with the requirements of this subparagraph."],[0,"(2) Scope of services and activities under plan of care"],[1,"A nursing facility must provide services and activities to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident in accordance with a written plan of care which—"],[2,"(A) describes the medical, nursing, and psychosocial needs of the resident and how such needs will be met;"],[2,"(B) is initially prepared, with the participation to the extent practicable of the resident or the resident's family or legal representative, by a team which includes the resident's attending physician and a registered professional nurse with responsibility for the resident; and"],[2,"(C) is periodically reviewed and revised by such team after each assessment under paragraph (3)."],[0,"(3) Residents' assessment"],[0,"(A) Requirement"],[2,"A nursing facility must conduct a comprehensive, accurate, standardized, reproducible assessment of each resident's functional capacity, which assessment—"],[3,"(i) describes the resident's capability to perform daily life functions and significant impairments in functional capacity;"],[3,"(ii) is based on a uniform minimum data set specified by the Secretary under subsection (f)(6)(A);"],[3,"(iii) uses an instrument which is specified by the State under subsection (e)(5); and"],[3,"(iv) includes the identification of medical problems."],[0,"(B) Certification"],[0,"(i) In general"],[3,"Each such assessment must be conducted or coordinated (with the appropriate participation of health professionals) by a registered professional nurse who signs and certifies the completion of the assessment. Each individual who completes a portion of such an assessment shall sign and certify as to the accuracy of that portion of the assessment."],[0,"(ii) Penalty for falsification"],[3,"(I) An individual who willfully and knowingly certifies under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $1,000 with respect to each assessment."],[3,"(II) An individual who willfully and knowingly causes another individual to certify under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $5,000 with respect to each assessment."],[3,"(III) The provisions of section 1320a–7a of this title (other than subsections (a) and (b)) shall apply to a civil money penalty under this clause in the same manner as such provisions apply to a penalty or proceeding under section 1320a–7a(a) of this title."],[0,"(iii) Use of independent assessors"],[3,"If a State determines, under a survey under subsection (g) or otherwise, that there has been a knowing and willful certification of false assessments under this paragraph, the State may require (for a period specified by the State) that resident assessments under this paragraph be conducted and certified by individuals who are independent of the facility and who are approved by the State."],[0,"(C) Frequency"],[0,"(i) In general"],[3,"Such an assessment must be conducted—"],[4,"(I) promptly upon (but no later than 14 days after the date of) admission for each individual admitted on or after October 1, 1990, and by not later than October 1, 1991, for each resident of the facility on that date;"],[4,"(II) promptly after a significant change in the resident's physical or mental condition; and"],[4,"(III) in no case less often than once every 12 months."],[0,"(ii) Resident review"],[3,"The nursing facility must examine each resident no less frequently than once every 3 months and, as appropriate, revise the resident's assessment to assure the continuing accuracy of the assessment."],[0,"(D) Use"],[2,"The results of such an assessment shall be used in developing, reviewing, and revising the resident's plan of care under paragraph (2)."],[0,"(E) Coordination"],[2,"Such assessments shall be coordinated with any State-required preadmission screening program to the maximum extent practicable in order to avoid duplicative testing and effort. In addition, a nursing facility shall notify the State mental health authority or State mental retardation or developmental disability authority, as applicable, promptly after a significant change in the physical or mental condition of a resident who is mentally ill or mentally retarded."],[0,"(F) Requirements relating to preadmission screening for mentally ill and mentally retarded individuals"],[2,"Except as provided in clauses (ii) and (iii) of subsection (e)(7)(A), a nursing facility must not admit, on or after January 1, 1989, any new resident who—"],[3,"(i) is mentally ill (as defined in subsection (e)(7)(G)(i)) unless the State mental health authority has determined (based on an independent physical and mental evaluation performed by a person or entity other than the State mental health authority) prior to admission that, because of the physical and mental condition of the individual, the individual requires the level of services provided by a nursing facility, and, if the individual requires such level of services, whether the individual requires specialized services for mental illness, or"],[3,"(ii) is mentally retarded (as defined in subsection (e)(7)(G)(ii)) unless the State mental retardation or developmental disability authority has determined prior to admission that, because of the physical and mental condition of the individual, the individual requires the level of services provided by a nursing facility, and, if the individual requires such level of services, whether the individual requires specialized services for mental retardation."],[2,"A State mental health authority and a State mental retardation or developmental disability authority may not delegate (by subcontract or otherwise) their responsibilities under this subparagraph to a nursing facility (or to an entity that has a direct or indirect affiliation or relationship with such a facility)."],[0,"(4) Provision of services and activities"],[0,"(A) In general"],[2,"To the extent needed to fulfill all plans of care described in paragraph (2), a nursing facility must provide (or arrange for the provision of)—"],[3,"(i) nursing and related services and specialized rehabilitative services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(ii) medically-related social services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(iii) pharmaceutical services (including procedures that assure the accurate acquiring, receiving, dispensing, and administering of all drugs and biologicals) to meet the needs of each resident;"],[3,"(iv) dietary services that assure that the meals meet the daily nutritional and special dietary needs of each resident;"],[3,"(v) an on-going program, directed by a qualified professional, of activities designed to meet the interests and the physical, mental, and psychosocial well-being of each resident;"],[3,"(vi) routine dental services (to the extent covered under the State plan) and emergency dental services to meet the needs of each resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396r?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1396r. Requirements for nursing facilities","tname":"The Public Health and Welfare","by":{"0":"2, 5, 5, 43, 45, 6, 40, 5, 43, 46, 46, 46, 6, 39, 41, 5, 41, 5, 41, 5, 41, 5, 41, 6, 41, 6, 41, 6, 41, 42","1":"3, 3, 25, 26, 27, 3, 30, 25, 3, 26, 27, 23, 4, 31, 34, 4, 32, 4, 4, 4, 4, 4, 30, 4, 5, 31, 5, 5, 33, 5, 5, 4, 34","2":"13, 33, 13, 33, 14, 39, 14, 33, 33, 14, 33, 14, 33, 39, 42, 16, 37, 40, 43","3":"19, 21, 16, 19, 21, 16, 19, 21, 22, 22, 16, 19, 21, 21, 21, 21, 16, 22"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":169,"ar":22,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"passim","1":"passim","2":"passim, 24","3":"passim"}},{"t":"usc","label":"20 U.S.C. § 1415","url":"https://www.law.cornell.edu/uscode/text/20/1415","subs":["(i)(3)(A)"],"by":{"0":"25"}},{"t":"usc","label":"29 U.S.C. § 794a","url":"https://www.law.cornell.edu/uscode/text/29/794a","subs":["(a)"],"by":{"0":"25"}},{"t":"reg","label":"42 C.F.R. § 431.220","url":"https://www.ecfr.gov/current/title-42/section-431.220","subs":["(a)(2)"],"by":{"0":"40"}},{"t":"reg","label":"42 C.F.R. § 431.240","url":"https://www.ecfr.gov/current/title-42/section-431.240","subs":["(a)(3)","(b)"],"by":{"0":"40, 40"}},{"t":"reg","label":"42 C.F.R. § 431.241","url":"https://www.ecfr.gov/current/title-42/section-431.241","subs":["(b)"],"by":{"0":"40"}},{"t":"reg","label":"42 C.F.R. § 431.242","url":"https://www.ecfr.gov/current/title-42/section-431.242","subs":["(a)","(b)","(e)"],"by":{"0":"40, 40, 40"}},{"t":"reg","label":"42 C.F.R. § 483.10","url":"https://www.ecfr.gov/current/title-42/section-483.10","subs":["(j)(1)","(j)(4)(i)","(j)(4)(v)","(j)(4)(vi)"],"by":{"0":"40, 40","3":"16, 17"}},{"t":"case","label":"M.H. Hoeflich and E. Perelmuter, The Anatomy of a Leading Case: Lawrence v. Fox in the Courts, the Casebooks, and the Commentaries","cite":"21 U. Mich. J.L. Reform 721","y":1988,"url":"https://www.courtlistener.com/c/U.%20Mich.%20J.L.%20Reform/21/721/","by":{"0":"17"}},{"t":"case","label":"Biden v. Missouri","cite":"142 S. Ct. 647","y":2022,"id":"2021/21a240","sc":1,"sum":"The Court grants the applications to stay the two injunctions barring the Secretary of Health and Human Services’ regulation requiring facilities that participate in Medicare and Medicaid to ensure that their employees are vaccinated against COVID–19.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2, 3"}},{"t":"case","label":"Bryson v. Shumway","cite":"308 F.3d 79","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/308/79/","by":{"1":"22"}},{"t":"case","label":"(III) Cases—Continued: Carter v. Stanton","cite":"405 U.S. 669","y":1972,"id":"1971/70-5082","sc":1,"op":1,"sum":"The District Court plainly had jurisdiction, and exhaustion is not required in the circumstances of this case. Damico v. California, 389 U. S. 416. If that court's characterization of the federal question as insubstantial was based on the face of the complaint, it was error; if the court treated the motion to dismiss as one for summary judgment, its order is unilluminating as to the relevant facts or the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Coventry Health Care of Missouri, Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Doe v. Chiles","cite":"136 F.3d 709","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/136/709/","by":{"1":"22"}},{"t":"case","label":"Doe v. Kidd","cite":"501 F.3d 348","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/501/348/","by":{"1":"21"}},{"t":"case","label":"Does v. Gillespie","cite":"867 F.3d 1034","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1034/","op":1,"ar":2,"by":{"1":"22"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"sum":"The Eleventh Amendment of the Constitution bars that portion of the District Court's decree that ordered retroactive pavment of benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 21","2":"1, 6, 23","3":"11"}},{"t":"case","label":"Fairholme Funds, Inc. v. United States","cite":"26 F.4th 1274","y":2022,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/26/1274/","by":{"1":"20"}},{"t":"case","label":"Hagans v. Lavine","cite":"415 U.S. 528","y":1974,"id":"1973/72-6476","sc":1,"sum":"Petitioners, recipients of public assistance under the federal-state Aid to Families with Dependent Children (AFDC) program, brought this action under 42 U. S..C. § 1983 and 28 U.S. C. § 2201 challenging a New York regulation permitting the State to recoup prior unscheduled payments for rent from subsequent grants under the AFDC program, on the ground that the regulation violated the Equal Protection Clause of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11","2":"6"}},{"t":"case","label":"Harris v. McRae","cite":"448 U.S. 297","y":1980,"id":"1979/79-1268","sc":1,"op":9,"sum":"Observing that our cases, running back to at least Page 1968, only mPakreoseonsfe Pif “elawnsd” inindeged mPeaunsb“llaiwcsa”.","sumSrc":"opinion","by":{"1":"17"}},{"t":"case","label":"Harris v. Olszewski","cite":"442 F.3d 456","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/442/456/","by":{"1":"22"}},{"t":"case","label":"Hendrick v. Lindsay","cite":"93 U.S. 143","y":1876,"id":"scdb/1876-033","sc":1,"op":1,"sum":"Concluding that “the right of a party to maintain assumpsit on a promise not under seal, made to another for his beneft, . . . is now the prevailing rule in this country”.","sumSrc":"opinion","by":{"1":"19","2":"28","3":"8"}},{"t":"case","label":"Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"1":"21, 24","2":"25"}},{"t":"case","label":"King v. Smith","cite":"392 U.S. 309","y":1968,"id":"1967/949","sc":1,"sum":"Alabama's substitute father regulation is invalid because it defines \"parent\" in a manner that is inconsistent with § 406 (a) of the Social Security Act, and in denying AFDC assistance to appellees on the basis of the invalid regulation Alabama has breached its federally imposed obligation to furnish aid to families with dependent children with reasonable promptness to all eligible individuals.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11","2":"5"}},{"t":"case","label":"Lawrence County v. Lead-Deadwood School District","cite":"469 U.S. 256","y":1985,"id":"1984/83-240","sc":1,"sum":"The state statute is invalid under the Supremacy Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Maine Community Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"1":"10"}},{"t":"case","label":"Miller v. Youakim","cite":"440 U.S. 125","y":1979,"id":"1978/77-742","sc":1,"sum":"The AFDC-FC program encompasses foster children who, pursuant to a judicial determination of neglect, have been placed in related homes that meet a State's licensing requirements for","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 29","2":"6, 23"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Center","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"sum":"The patients have no interest in receiving benefits for care in a particular facility that entitles them, as a matter of constitutional law, to a hearing before HEW and DPW can decertify that facility. Whatever legal rights the patients may have against the nursing home for failing to maintain its status as a qualified nursing home, the enforcement by HEW and DPW of their valid regulations did not directly affect …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Planned Parenthood South Atlantic v. Kerr","cite":"27 F.4th 945","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/27/945/","by":{"1":"22"}},{"t":"case","label":"Quern v. Mandley","cite":"436 U.S. 725","y":1978,"id":"1977/76-1159","sc":1,"sum":"This litigation originated as a challenge to the validity of Illinois' Emergency Assistance to Needy Families with Children (EA) program under Title IV-A of the Social Security Act (SSA). The Court of Appeals, reversing the District Court, first held that the program was invalid because it limited eligibility for such assistance more narrowly than § 406 (e) (1) of the SSA, which makes federal matching funds …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11","2":"6"}},{"t":"case","label":"Robinson v. Chamberlain","cite":"34 N.Y. 389","y":1866,"url":"https://www.courtlistener.com/c/N.Y./34/389/","sum":"Noting that, under state act that authorized contract, defendant was vested “with the power to bring suits in behalf of the State” and with police power to “to seize and detain all boats”.","sumSrc":"brief:3","by":{"1":"20","3":"9"}},{"t":"case","label":"Romano v. Greenstein","cite":"721 F.3d 373","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/721/373/","by":{"1":"21"}},{"t":"case","label":"S.D. ex rel. Dickson v. Hood","cite":"391 F.3d 581","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/391/581/","by":{"1":"22"}},{"t":"case","label":"Sabree v. Richman","cite":"367 F.3d 180","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/367/180/","by":{"1":"22"}},{"t":"case","label":"Smith v. Robinson","cite":"468 U.S. 992","y":1984,"id":"1983/82-2120","sc":1,"op":6,"sum":"When the Superintendent of Schools in Cumberland, R. I., informed petitioner parents of petitioner child, who suffers from cerebral palsy and other handicaps, that the School Committee no longer would fund the child's placement in a special educational program, the parents, in addition to appealing the Superintendent's decision to the School Committee and thereafter through the state administrative process, filed an …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","3":"15, 17"}},{"t":"case","label":"Steward Machine Co. v. Davis","cite":"301 U.S. 548","y":1937,"id":"1900-1940/301us548","sc":1,"op":5,"sum":"The Court held that the tax under the Social Security Act was a constitutional exercise of congressional power.","sumSrc":"Oyez","by":{"1":"16","2":"30"}},{"t":"case","label":"Townsend v. Swank","cite":"404 U.S. 282","y":1971,"id":"1971/70-5021","sc":1,"op":1,"sum":"Under § 402 (a) (10) of the Social Security Act, a state participating plan under the AFDC program must provide that aid to families with dependent children shall be furnished with reasonable promptness to \"all eligible\" individuals. Since § 406 (a) (2) (B) of the Act makes dependent 18-20-year-olds eligible for benefits whether attending a college or university or a vocational or technical training course, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11","2":"5, 6, 23"}},{"t":"case","label":"Van Lare v. Hurley","cite":"421 U.S. 338","y":1975,"id":"1974/74-453","sc":1,"sum":"The New York \"lodger\" regulations, which are based on the assumption that the nonpaying lodger is contributing to the welfare of the household, without inquiry into whether he in fact does sioner, Department of Social Services of New York, et al., on certiorari to the United States Court of Appeals for the Second Circuit. VAN LARE v. HURLEY","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11","2":"6, 23"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 1997","url":"https://www.law.cornell.edu/uscode/text/42/1997","subs":["(1)(A)","(1)(B)(v)","(2)"],"stext":{"head":"§1997. Definitions","paras":[[0,"As used in this subchapter—"],[0,"(1) The term \"institution\" means any facility or institution—"],[1,"(A) which is owned, operated, or managed by, or provides services on behalf of any State or political subdivision of a State; and"],[1,"(B) which is—"],[2,"(i) for persons who are mentally ill, disabled, or retarded, or chronically ill or handicapped;"],[2,"(ii) a jail, prison, or other correctional facility;"],[2,"(iii) a pretrial detention facility;"],[2,"(iv) for juveniles—"],[3,"(I) held awaiting trial;"],[3,"(II) residing in such facility or institution for purposes of receiving care or treatment; or"],[3,"(III) residing for any State purpose in such facility or institution (other than a residential facility providing only elementary or secondary education that is not an institution in which reside juveniles who are adjudicated delinquent, in need of supervision, neglected, placed in State custody, mentally ill or disabled, mentally retarded, or chronically ill or handicapped); or"],[2,"(v) providing skilled nursing, intermediate or long-term care, or custodial or residential care."],[0,"(2) Privately owned and operated facilities shall not be deemed \"institutions\" under this subchapter if—"],[1,"(A) the licensing of such facility by the State constitutes the sole nexus between such facility and such State;"],[1,"(B) the receipt by such facility, on behalf of persons residing in such facility, of payments under title XVI, XVIII [42 U.S.C. 1381 et seq., 1395 et seq.], or under a State plan approved under title XIX [42 U.S.C. 1396 et seq.], of the Social Security Act, constitutes the sole nexus between such facility and such State; or"],[1,"(C) the licensing of such facility by the State, and the receipt by such facility, on behalf of persons residing in such facility, of payments under title XVI, XVIII [42 U.S.C. 1381 et seq., 1395 et seq.], or under a State plan approved under title XIX [42 U.S.C. 1396 et seq.], of the Social Security Act, constitutes the sole nexus between such facility and such State;"],[0,"(3) The term \"person\" means an individual, a trust or estate, a partnership, an association, or a corporation;"],[0,"(4) The term \"State\" means any of the several States, the District of Columbia, the Commonwealth of Puerto Rico, or any of the territories and possessions of the United States;"],[0,"(5) The term \"legislative days\" means any calendar day on which either House of Congress is in session."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997?type=usc&year=mostrecent&link-type=html"},"head":"§1997. Definitions","tname":"The Public Health and Welfare","by":{"1":"34","2":"6, 7, 7, 7"}},{"t":"usc","label":"42 U.S.C. § 15001","url":"https://www.law.cornell.edu/uscode/text/42/15001","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 1320a-2","url":"https://www.law.cornell.edu/uscode/text/42/1320a-2","stext":{"head":"§1320a–2. Effect of failure to carry out State plan","paras":[[0,"In an action brought to enforce a provision of this chapter, such provision is not to be deemed unenforceable because of its inclusion in a section of this chapter requiring a State plan or specifying the required contents of a State plan. This section is not intended to limit or expand the grounds for determining the availability of private actions to enforce State plan requirements other than by overturning any such grounds applied in Suter v. Artist M., 112 S. Ct. 1360 (1992), but not applied in prior Supreme Court decisions respecting such enforceability; provided, however, that this section is not intended to alter the holding in Suter v. Artist M. that section 671(a)(15) of this title is not enforceable in a private right of action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-2?type=usc&year=mostrecent&link-type=html"},"head":"§1320a–2. Effect of failure to carry out State plan","tname":"The Public Health and Welfare","by":{"1":"14","2":"11, 22","3":"13"}},{"t":"law","label":"Pub. L. No. 100-203","url":"https://www.govinfo.gov/link/statute/101/1330","by":{"1":"3","2":"11"}},{"t":"usc","label":"31 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/31/6901","by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 10801","url":"https://www.law.cornell.edu/uscode/text/42/10801","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","stext":{"head":"§301. Authorization of appropriations","paras":[[0,"For the purpose of enabling each State, as far as practicable under the conditions in such State, to furnish financial assistance to aged needy individuals, there is hereby authorized to be appropriated for each fiscal year a sum sufficient to carry out the purposes of this subchapter. The sums made available under this section shall be used for making payments to States which have submitted, and had approved by the Secretary of Health and Human Services (hereinafter referred to as the \"Secretary\"), State plans for old-age assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/301?type=usc&year=mostrecent&link-type=html"},"head":"§301. Authorization of appropriations","tname":"The Public Health and Welfare","by":{"1":"1","2":"1"}},{"t":"usc","label":"42 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/42/601","stext":{"head":"§601. Purpose","paras":[[0,"(a) In general"],[0,"The purpose of this part is to increase the flexibility of States in operating a program designed to—"],[1,"(1) provide assistance to needy families so that children may be cared for in their own homes or in the homes of relatives;"],[1,"(2) end the dependence of needy parents on government benefits by promoting job preparation, work, and marriage;"],[1,"(3) prevent and reduce the incidence of out-of-wedlock pregnancies and establish annual numerical goals for preventing and reducing the incidence of these pregnancies; and"],[1,"(4) encourage the formation and maintenance of two-parent families."],[0,"(b) No individual entitlement"],[0,"This part shall not be interpreted to entitle any individual or family to assistance under any State program funded under this part."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/601?type=usc&year=mostrecent&link-type=html"},"head":"§601. Purpose","tname":"The Public Health and Welfare","by":{"1":"12","2":"10, 11"}},{"t":"usc","label":"42 U.S.C. § 671","url":"https://www.law.cornell.edu/uscode/text/42/671","subs":["(a)(15)(1988)","(a)","(a)(15)"],"stext":{"head":"§671. State plan for foster care and adoption assistance","paras":[[0,"(a) Requisite features of State plan"],[0,"In order for a State to be eligible for payments under this part, it shall have a plan approved by the Secretary which—"],[1,"(1) provides for foster care maintenance payments in accordance with section 672 of this title, adoption assistance in accordance with section 673 of this title, and, at the option of the State, services or programs specified in subsection (e)(1) of this section for children who are candidates for foster care or who are pregnant or parenting foster youth and the parents or kin caregivers of the children, in accordance with the requirements of that subsection;"],[1,"(2) provides that the State agency responsible for administering the program authorized by subpart 1 of part B of this subchapter shall administer, or supervise the administration of, the program authorized by this part;"],[1,"(3) provides that the plan shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(4) provides that the State shall assure that the programs at the local level assisted under this part will be coordinated with the programs at the State or local level assisted under parts A and B of this subchapter, under division A 1 of subchapter XX of this chapter, and under any other appropriate provision of Federal law;"],[1,"(5) provides that the State will, in the administration of its programs under this part, use such methods relating to the establishment and maintenance of personnel standards on a merit basis as are found by the Secretary to be necessary for the proper and efficient operation of the programs, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, or compensation of any individual employed in accordance with such methods;"],[1,"(6) provides that the State agency referred to in paragraph (2) (hereinafter in this part referred to as the \"State agency\") will make such reports, in such form and containing such information as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provides that the State agency will monitor and conduct periodic evaluations of activities carried out under this part;"],[1,"(8) subject to subsection (c), provides safeguards which restrict the use of or disclosure of information concerning individuals assisted under the State plan to purposes directly connected with (A) the administration of the plan of the State approved under this part, the plan or program of the State under part A, B, or D of this subchapter or under subchapter I, V, X, XIV, XVI (as in effect in Puerto Rico, Guam, and the Virgin Islands), XIX, or XX, the program established by subchapter II, or the supplemental security income program established by subchapter XVI, (B) any investigation, prosecution, or criminal or civil proceeding, conducted in connection with the administration of any such plan or program, (C) the administration of any other Federal or federally assisted program which provides assistance, in cash or in kind, or services, directly to individuals on the basis of need, (D) any audit or similar activity conducted in connection with the administration of any such plan or program by any governmental agency which is authorized by law to conduct such audit or activity, and (E) reporting and providing information pursuant to paragraph (9) to appropriate authorities with respect to known or suspected child abuse or neglect; and the safeguards so provided shall prohibit disclosure, to any committee or legislative body (other than an agency referred to in clause (D) with respect to an activity referred to in such clause), of any information which identifies by name or address any such applicant or recipient; except that nothing contained herein shall preclude a State from providing standards which restrict disclosures to purposes more limited than those specified herein, or which, in the case of adoptions, prevent disclosure entirely;"],[1,"(9) provides that the State agency will—"],[2,"(A) report to an appropriate agency or official, known or suspected instances of physical or mental injury, sexual abuse or exploitation, or negligent treatment or maltreatment of a child receiving aid under part B or this part under circumstances which indicate that the child's health or welfare is threatened thereby;"],[2,"(B) provide such information with respect to a situation described in subparagraph (A) as the State agency may have; and"],[2,"(C) not later than—"],[3,"(i) 1 year after September 29, 2014, demonstrate to the Secretary that the State agency has developed, in consultation with State and local law enforcement, juvenile justice systems, health care providers, education agencies, and organizations with experience in dealing with at-risk children and youth, policies and procedures (including relevant training for caseworkers) for identifying, documenting in agency records, and determining appropriate services with respect to—"],[4,"(I) any child or youth over whom the State agency has responsibility for placement, care, or supervision and who the State has reasonable cause to believe is, or is at risk of being, a sex trafficking victim (including children for whom a State child welfare agency has an open case file but who have not been removed from the home, children who have run away from foster care and who have not attained 18 years of age or such older age as the State has elected under section 675(8) of this title, and youth who are not in foster care but are receiving services under section 677 of this title); and"],[4,"(II) at the option of the State, any individual who has not attained 26 years of age, without regard to whether the individual is or was in foster care under the responsibility of the State; and"],[3,"(ii) 2 years after September 29, 2014, demonstrate to the Secretary that the State agency is implementing the policies and procedures referred to in clause (i)."],[1,"(10) provides—"],[2,"(A) for the establishment or designation of a State authority or authorities that shall be responsible for establishing and maintaining standards for foster family homes and child care institutions which are reasonably in accord with recommended standards of national organizations concerned with standards for the institutions or homes, including standards related to admission policies, safety, sanitation, and protection of civil rights, and which shall permit use of the reasonable and prudent parenting standard;"],[2,"(B) that the standards established pursuant to subparagraph (A) shall be applied by the State to any foster family home or child care institution receiving funds under this part or part B and shall require, as a condition of each contract entered into by a child care institution to provide foster care, the presence on-site of at least 1 official who, with respect to any child placed at the child care institution, is designated to be the caregiver who is authorized to apply the reasonable and prudent parent standard to decisions involving the participation of the child in age or developmentally-appropriate activities, and who is provided with training in how to use and apply the reasonable and prudent parent standard in the same manner as prospective foster parents are provided the training pursuant to paragraph (24);"],[2,"(C) that the standards established pursuant to subparagraph (A) shall include policies related to the liability of foster parents and private entities under contract by the State involving the application of the reasonable and prudent parent standard, to ensure appropriate liability for caregivers when a child participates in an approved activity and the caregiver approving the activity acts in accordance with the reasonable and prudent parent standard; and"],[2,"(D) that a waiver of any standards established pursuant to subparagraph (A) may be made only on a case-by-case basis for nonsafety standards (as determined by the State) in relative foster family homes for specific children in care;"],[1,"(11) provides for periodic review of the standards referred to in the preceding paragraph and amounts paid as foster care maintenance payments and adoption assistance to assure their continuing appropriateness;"],[1,"(12) provides for granting an opportunity for a fair hearing before the State agency to any individual whose claim for benefits available pursuant to this part is denied or is not acted upon with reasonable promptness;"],[1,"(13) provides that the State shall arrange for a periodic and independently conducted audit of the programs assisted under this part and part B of this subchapter, which shall be conducted no less frequently than once every three years;"],[1,"(14) provides (A) specific goals (which shall be established by State law on or before October 1, 1982) for each fiscal year (commencing with the fiscal year which begins on October 1, 1983) as to the maximum number of children (in absolute numbers or as a percentage of all children in foster care with respect to whom assistance under the plan is provided during such year) who, at any time during such year, will remain in foster care after having been in such care for a period in excess of twenty-four months, and (B) a description of the steps which will be taken by the State to achieve such goals;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/671?type=usc&year=mostrecent&link-type=html"},"head":"§671. State plan for foster care and adoption assistance","tname":"The Public Health and Welfare","by":{"1":"12","2":"10, 11","3":"13"}},{"t":"usc","label":"42 U.S.C. § 1395","url":"https://www.law.cornell.edu/uscode/text/42/1395","stext":{"head":"§1395. Prohibition against any Federal interference","paras":[[0,"Nothing in this subchapter shall be construed to authorize any Federal officer or employee to exercise any supervision or control over the practice of medicine or the manner in which medical services are provided, or over the selection, tenure, or compensation of any officer or employee of any institution, agency, or person providing health services; or to exercise any supervision or control over the administration or operation of any such institution, agency, or person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395?type=usc&year=mostrecent&link-type=html"},"head":"§1395. Prohibition against any Federal interference","tname":"The Public Health and Welfare","by":{"1":"1","2":"13"}},{"t":"usc","label":"42 U.S.C. § 1395i-3","url":"https://www.law.cornell.edu/uscode/text/42/1395i-3","subs":["(c)","(c)(1)(A)","(c)(1)(A)(ii)","(c)(1)(A)(ii)(I)","(c)(1)(A)(vi)","(c)(2)","(c)(2)(A)","(c)(2)(A)(i)","(e)(3)","(g)(1)(A)","(g)(2)","(g)(2)(A)(ii)(III)","(g)(2)(B)","(g)(3)","(g)(4)","(g)(5)","(h)","(h)(2)(B)(ii)(IV)(ff)","(h)(5)"],"stext":{"head":"§1395i–3. Requirements for, and assuring quality of care in, skilled nursing facilities","paras":[[0,"(a) \"Skilled nursing facility\" defined"],[0,"In this subchapter, the term \"skilled nursing facility\" means an institution (or a distinct part of an institution) which—"],[1,"(1) is primarily engaged in providing to residents—"],[2,"(A) skilled nursing care and related services for residents who require medical or nursing care, or"],[2,"(B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons,"],[1,"and is not primarily for the care and treatment of mental diseases;"],[1,"(2) has in effect a transfer agreement (meeting the requirements of section 1395x(l) of this title) with one or more hospitals having agreements in effect under section 1395cc of this title; and"],[1,"(3) meets the requirements for a skilled nursing facility described in subsections (b), (c), and (d) of this section."],[0,"(b) Requirements relating to provision of services"],[0,"(1) Quality of life"],[0,"(A) In general"],[2,"A skilled nursing facility must care for its residents in such a manner and in such an environment as will promote maintenance or enhancement of the quality of life of each resident."],[0,"(B) Quality assessment and assurance"],[2,"A skilled nursing facility must maintain a quality assessment and assurance committee, consisting of the director of nursing services, a physician designated by the facility, and at least 3 other members of the facility's staff, which (i) meets at least quarterly to identify issues with respect to which quality assessment and assurance activities are necessary and (ii) develops and implements appropriate plans of action to correct identified quality deficiencies. A State or the Secretary may not require disclosure of the records of such committee except insofar as such disclosure is related to the compliance of such committee with the requirements of this subparagraph."],[0,"(2) Scope of services and activities under plan of care"],[1,"A skilled nursing facility must provide services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident, in accordance with a written plan of care which—"],[2,"(A) describes the medical, nursing, and psychosocial needs of the resident and how such needs will be met;"],[2,"(B) is initially prepared, with the participation to the extent practicable of the resident or the resident's family or legal representative, by a team which includes the resident's attending physician and a registered professional nurse with responsibility for the resident; and"],[2,"(C) is periodically reviewed and revised by such team after each assessment under paragraph (3)."],[0,"(3) Residents' assessment"],[0,"(A) Requirement"],[2,"A skilled nursing facility must conduct a comprehensive, accurate, standardized, reproducible assessment of each resident's functional capacity, which assessment—"],[3,"(i) describes the resident's capability to perform daily life functions and significant impairments in functional capacity;"],[3,"(ii) is based on a uniform minimum data set specified by the Secretary under subsection (f)(6)(A);"],[3,"(iii) uses an instrument which is specified by the State under subsection (e)(5); and"],[3,"(iv) includes the identification of medical problems."],[0,"(B) Certification"],[0,"(i) In general"],[3,"Each such assessment must be conducted or coordinated (with the appropriate participation of health professionals) by a registered professional nurse who signs and certifies the completion of the assessment. Each individual who completes a portion of such an assessment shall sign and certify as to the accuracy of that portion of the assessment."],[0,"(ii) Penalty for falsification"],[3,"(I) An individual who willfully and knowingly certifies under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $1,000 with respect to each assessment."],[3,"(II) An individual who willfully and knowingly causes another individual to certify under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $5,000 with respect to each assessment."],[3,"(III) The provisions of section 1320a–7a of this title (other than subsections (a) and (b)) shall apply to a civil money penalty under this clause in the same manner as such provisions apply to a penalty or proceeding under section 1320a–7a(a) of this title."],[0,"(iii) Use of independent assessors"],[3,"If a State determines, under a survey under subsection (g) or otherwise, that there has been a knowing and willful certification of false assessments under this paragraph, the State may require (for a period specified by the State) that resident assessments under this paragraph be conducted and certified by individuals who are independent of the facility and who are approved by the State."],[0,"(C) Frequency"],[0,"(i) In general"],[3,"Subject to the timeframes prescribed by the Secretary under section 1395yy(e)(6) of this title, such an assessment must be conducted—"],[4,"(I) promptly upon (but no later than 14 days after the date of) admission for each individual admitted on or after October 1, 1990, and by not later than January 1, 1991, for each resident of the facility on that date;"],[4,"(II) promptly after a significant change in the resident's physical or mental condition; and"],[4,"(III) in no case less often than once every 12 months."],[0,"(ii) Resident review"],[3,"The skilled nursing facility must examine each resident no less frequently than once every 3 months and, as appropriate, revise the resident's assessment to assure the continuing accuracy of the assessment."],[0,"(D) Use"],[2,"The results of such an assessment shall be used in developing, reviewing, and revising the resident's plan of care under paragraph (2)."],[0,"(E) Coordination"],[2,"Such assessments shall be coordinated with any State-required preadmission screening program to the maximum extent practicable in order to avoid duplicative testing and effort."],[0,"(4) Provision of services and activities"],[0,"(A) In general"],[2,"To the extent needed to fulfill all plans of care described in paragraph (2), a skilled nursing facility must provide, directly or under arrangements (or, with respect to dental services, under agreements) with others for the provision of—"],[3,"(i) nursing services and specialized rehabilitative services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(ii) medically-related social services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(iii) pharmaceutical services (including procedures that assure the accurate acquiring, receiving, dispensing, and administering of all drugs and biologicals) to meet the needs of each resident;"],[3,"(iv) dietary services that assure that the meals meet the daily nutritional and special dietary needs of each resident;"],[3,"(v) an on-going program, directed by a qualified professional, of activities designed to meet the interests and the physical, mental, and psychosocial well-being of each resident;"],[3,"(vi) routine and emergency dental services to meet the needs of each resident; and"],[3,"(vii) treatment and services required by mentally ill and mentally retarded residents not otherwise provided or arranged for (or required to be provided or arranged for) by the State."],[2,"The services provided or arranged by the facility must meet professional standards of quality. Nothing in clause (vi) shall be construed as requiring a facility to provide or arrange for dental services described in that clause without additional charge."],[0,"(B) Qualified persons providing services"],[2,"Services described in clauses (i), (ii), (iii), (iv), and (vi) of subparagraph (A) must be provided by qualified persons in accordance with each resident's written plan of care."],[0,"(C) Required nursing care"],[0,"(i) In general"],[3,"Except as provided in clause (ii), a skilled nursing facility must provide 24-hour licensed nursing service which is sufficient to meet nursing needs of its residents and must use the services of a registered professional nurse at least 8 consecutive hours a day, 7 days a week."],[0,"(ii) Exception"],[3,"To the extent that clause (i) may be deemed to require that a skilled nursing facility engage the services of a registered professional nurse for more than 40 hours a week, the Secretary is authorized to waive such requirement if the Secretary finds that—"],[4,"(I) the facility is located in a rural area and the supply of skilled nursing facility services in such area is not sufficient to meet the needs of individuals residing therein,"],[4,"(II) the facility has one full-time registered professional nurse who is regularly on duty at such facility 40 hours a week,"],[4,"(III) the facility either has only patients whose physicians have indicated (through physicians' orders or admission notes) that each such patient does not require the services of a registered nurse or a physician for a 48-hour period, or has made arrangements for a registered professional nurse or a physician to spend such time at such facility as may be indicated as necessary by the physician to provide necessary skilled nursing services on days when the regular full-time registered professional nurse is not on duty,"],[4,"(IV) the Secretary provides notice of the waiver to the State long-term care ombudsman (established under section 307(a)(12) 1 of the Older Americans Act of 1965) and the protection and advocacy system in the State for the mentally ill and the mentally retarded, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395i-3?type=usc&year=mostrecent&link-type=html"},"head":"§1395i–3. Requirements for, and assuring quality of care in, skilled nursing facilities","tname":"The Public Health and Welfare","by":{"1":"3, 3, 25, 26, 3, 3, 25, 26, 27, 3, 30, 25, 3, 26, 27, 4, 4, 32, 4, 4, 4, 4, 4, 4, 5, 31, 33, 34","2":"13"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","stext":{"head":"§1396. Medicaid and CHIP Payment and Access Commission","paras":[[0,"(a) Establishment"],[0,"There is hereby established the Medicaid and CHIP Payment and Access Commission (in this section referred to as \"MACPAC\")."],[0,"(b) Duties"],[0,"(1) Review of access policies for all States and annual reports"],[1,"MACPAC shall—"],[2,"(A) review policies of the Medicaid program established under this subchapter (in this section referred to as \"Medicaid\") and the State Children's Health Insurance Program established under subchapter XXI (in this section referred to as \"CHIP\") affecting access to covered items and services, including topics described in paragraph (2);"],[2,"(B) make recommendations to Congress, the Secretary, and States concerning such access policies;"],[2,"(C) by not later than March 15 of each year (beginning with 2010), submit a report to Congress containing the results of such reviews and MACPAC's recommendations concerning such policies; and"],[2,"(D) by not later than June 15 of each year (beginning with 2010), submit a report to Congress containing an examination of issues affecting Medicaid and CHIP, including the implications of changes in health care delivery in the United States and in the market for health care services on such programs."],[0,"(2) Specific topics to be reviewed"],[1,"Specifically, MACPAC shall review and assess the following:"],[0,"(A) Medicaid and CHIP payment policies"],[2,"Payment policies under Medicaid and CHIP, including—"],[3,"(i) the factors affecting expenditures for the efficient provision of items and services in different sectors, including the process for updating payments to medical, dental, and health professionals, hospitals, residential and long-term care providers, providers of home and community based services, Federally-qualified health centers and rural health clinics, managed care entities, and providers of other covered items and services;"],[3,"(ii) payment methodologies; and"],[3,"(iii) the relationship of such factors and methodologies to access and quality of care for Medicaid and CHIP beneficiaries (including how such factors and methodologies enable such beneficiaries to obtain the services for which they are eligible, affect provider supply, and affect providers that serve a disproportionate share of low-income and other vulnerable populations)."],[0,"(B) Eligibility policies"],[2,"Medicaid and CHIP eligibility policies, including a determination of the degree to which Federal and State policies provide health care coverage to needy populations."],[0,"(C) Enrollment and retention processes"],[2,"Medicaid and CHIP enrollment and retention processes, including a determination of the degree to which Federal and State policies encourage the enrollment of individuals who are eligible for such programs and screen out individuals who are ineligible, while minimizing the share of program expenses devoted to such processes."],[0,"(D) Coverage policies"],[2,"Medicaid and CHIP benefit and coverage policies, including a determination of the degree to which Federal and State policies provide access to the services enrollees require to improve and maintain their health and functional status."],[0,"(E) Quality of care"],[2,"Medicaid and CHIP policies as they relate to the quality of care provided under those programs, including a determination of the degree to which Federal and State policies achieve their stated goals and interact with similar goals established by other purchasers of health care services."],[0,"(F) Interaction of Medicaid and CHIP payment policies with health care delivery generally"],[2,"The effect of Medicaid and CHIP payment policies on access to items and services for children and other Medicaid and CHIP populations other than under this subchapter or subchapter XXI and the implications of changes in health care delivery in the United States and in the general market for health care items and services on Medicaid and CHIP."],[0,"(G) Interactions with Medicare and Medicaid"],[2,"Consistent with paragraph (11), the interaction of policies under Medicaid and the Medicare program under subchapter XVIII, including with respect to how such interactions affect access to services, payments, and dual eligible individuals."],[0,"(H) Other access policies"],[2,"The effect of other Medicaid and CHIP policies on access to covered items and services, including policies relating to transportation and language barriers and preventive, acute, and long-term services and supports."],[0,"(3) Recommendations and reports of State-specific data"],[1,"MACPAC shall—"],[2,"(A) review national and State-specific Medicaid and CHIP data; and"],[2,"(B) submit reports and recommendations to Congress, the Secretary, and States based on such reviews."],[0,"(4) Creation of early-warning system"],[1,"MACPAC shall create an early-warning system to identify provider shortage areas, as well as other factors that adversely affect, or have the potential to adversely affect, access to care by, or the health care status of, Medicaid and CHIP beneficiaries. MACPAC shall include in the annual report required under paragraph (1)(D) a description of all such areas or problems identified with respect to the period addressed in the report."],[0,"(5) Comments on certain secretarial reports and regulations"],[0,"(A) Certain secretarial reports"],[2,"If the Secretary submits to Congress (or a committee of Congress) a report that is required by law and that relates to access policies, including with respect to payment policies, under Medicaid or CHIP, the Secretary shall transmit a copy of the report to MACPAC. MACPAC shall review the report and, not later than 6 months after the date of submittal of the Secretary's report to Congress, shall submit to the appropriate committees of Congress and the Secretary written comments on such report. Such comments may include such recommendations as MACPAC deems appropriate."],[0,"(B) Regulations"],[2,"MACPAC shall review Medicaid and CHIP regulations and may comment through submission of a report to the appropriate committees of Congress and the Secretary, on any such regulations that affect access, quality, or efficiency of health care."],[0,"(6) Agenda and additional reviews"],[0,"(A) In general"],[2,"MACPAC shall consult periodically with the chairmen and ranking minority members of the appropriate committees of Congress regarding MACPAC's agenda and progress towards achieving the agenda. MACPAC may conduct additional reviews, and submit additional reports to the appropriate committees of Congress, from time to time on such topics relating to the program under this subchapter or subchapter XXI as may be requested by such chairmen and members and as MACPAC deems appropriate."],[0,"(B) Review and reports regarding Medicaid DSH"],[0,"(i) In general"],[3,"MACPAC shall review and submit an annual report to Congress on disproportionate share hospital payments under section 1396r–4 of this title. Each report shall include the information specified in clause (ii)."],[0,"(ii) Required report information"],[3,"Each report required under this subparagraph shall include the following:"],[4,"(I) Data relating to changes in the number of uninsured individuals."],[4,"(II) Data relating to the amount and sources of hospitals' uncompensated care costs, including the amount of such costs that are the result of providing unreimbursed or under-reimbursed services, charity care, or bad debt."],[4,"(III) Data identifying hospitals with high levels of uncompensated care that also provide access to essential community services for low-income, uninsured, and vulnerable populations, such as graduate medical education, and the continuum of primary through quarternary care, including the provision of trauma care and public health services."],[4,"(IV) State-specific analyses regarding the relationship between the most recent State DSH allotment and the projected State DSH allotment for the succeeding year and the data reported under subclauses (I), (II), and (III) for the State."],[0,"(iii) Data"],[3,"Notwithstanding any other provision of law, the Secretary regularly shall provide MACPAC with the most recent State reports and most recent independent certified audits submitted under section 1396r–4(j) of this title, cost reports submitted under subchapter XVIII, and such other data as MACPAC may request for purposes of conducting the reviews and preparing and submitting the annual reports required under this subparagraph."],[0,"(iv) Submission deadlines"],[3,"The first report required under this subparagraph shall be submitted to Congress not later than February 1, 2016. Subsequent reports shall be submitted as part of, or with, each annual report required under paragraph (1)(C) during the period of fiscal years 2017 through 2024."],[0,"(7) Availability of reports"],[1,"MACPAC shall transmit to the Secretary a copy of each report submitted under this subsection and shall make such reports available to the public."],[0,"(8) Appropriate committee of Congress"],[1,"For purposes of this section, the term \"appropriate committees of Congress\" means the Committee on Energy and Commerce of the House of Representatives and the Committee on Finance of the Senate."],[0,"(9) Voting and reporting requirements"],[1,"With respect to each recommendation contained in a report submitted under paragraph (1), each member of MACPAC shall vote on the recommendation, and MACPAC shall include, by member, the results of that vote in the report containing the recommendation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396?type=usc&year=mostrecent&link-type=html"},"head":"§1396. Medicaid and CHIP Payment and Access Commission","tname":"The Public Health and Welfare","by":{"1":"2","2":"13, 33"}},{"t":"usc","label":"42 U.S.C. § 1396c","url":"https://www.law.cornell.edu/uscode/text/42/1396c","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1320a-10","url":"https://www.law.cornell.edu/uscode/text/42/1320a-10","stext":{"head":"§1320a–10. Effect of failure to carry out State plan","paras":[[0,"In an action brought to enforce a provision of this chapter, such provision is not to be deemed unenforceable because of its inclusion in a section of this chapter requiring a State plan or specifying the required contents of a State plan. This section is not intended to limit or expand the grounds for determining the availability of private actions to enforce State plan requirements other than by overturning any such grounds applied in Suter v. Artist M., 112 S. Ct. 1360 (1992), but not applied in prior Supreme Court decisions respecting such enforceability: Provided, however, That this section is not intended to alter the holding in Suter v. Artist M. that section 671(a)(15) of this title is not enforceable in a private right of action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-10?type=usc&year=mostrecent&link-type=html"},"head":"§1320a–10. Effect of failure to carry out State plan","tname":"The Public Health and Welfare","by":{"1":"14","2":"11, 22","3":"13"}},{"t":"reg","label":"86 Fed. Reg. 42,424","url":"https://www.govinfo.gov/link/fr/86/42424","by":{"1":"2, 30"}},{"t":"case","label":"Ariz. State Legislature v. Ariz. Indep. Redistricting Comm’n","cite":"576 U.S. 787","y":2015,"id":"2014/13-1314","sc":1,"sum":"The Court determined that the Elections Clause of the U.S. Constitution does not prohibit a state from creating an independent redistricting commission by initiative.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Becerra v. Empire Health Found.","cite":"142 S. Ct. 2354","y":2022,"id":"2021/20-1312","sc":1,"op":1,"sum":"For purposes of calculating the Medicare fraction—one of two fractions the Medicare program uses to adjust the rates paid to hospitals that serve a higher-than-usual percentage of low-income patients—those individuals “entitled to [Medicare Part A] benefits” are all those qualifying for the program, regardless of whether they receive Medicare payments for part or all of a hospital stay.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"43"}},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22"}},{"t":"case","label":"Bomar v. Keyes","cite":"162 F.2d 136","y":1947,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/162/136/","by":{"2":"5"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Burns v. Alcala","cite":"420 U.S. 575","y":1975,"id":"1974/73-1708","sc":1,"sum":"The Supreme Court held that the legislative history surrounding the Social Security Act did not provide a basis for including unborn children in the definition of “dependent children”. While some states had adopted welfare plans that included unborn children, it was not required in order to comply with federal law. The Court also remanded the case for consideration of the Fourteenth Amendment issues.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Cal. Dep’t of Hum. Res. Dev. v. Java","cite":"402 U.S. 121","y":1971,"id":"1970/507","sc":1,"sum":"Section 303 (a) (1) of the Social Security Act requires a method of administration \"reasonably calculated to insure full payment of unemployment compensation when due.\" In light of the intent of Congress to make payments available at the earliest stage of unemployment as is administratively feasible, in order to provide a substitute for wages, the language \"when due\" must be construed to mean when benefits are …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5, 23"}},{"t":"case","label":"Carleson v. Remillard","cite":"406 U.S. 598","y":1972,"id":"1971/70-250","sc":1,"sum":"Section 402 (a) (10) of the Social Security Act imposes on each State participating in the AFDC program the requirement that benefits \"shall be furnished with reasonable promptness to all eligible individuals.\" Under the Act the eligibility criterion of \"continued absence\" of a parent from the home means that the parent may be absent for any reason. Consequently, that criterion applies to one who is absent by reason …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 23"}},{"t":"case","label":"Cort v. Ash","cite":"422 U.S. 66","y":1975,"id":"1974/73-1908","sc":1,"sum":"Respondent stockholder brought this action seeking damages in favor of petitioner Bethlehem Steel Corp., a Delaware corporation, and injunctive relief because of advertisements in connection with the 1972 Presidential election that petitioner corporate directors had authorized from general corporate funds in alleged violation of 18 U. S. C. § 610, which prohibits corporations from making contributions or …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Crawford-El v. Britton","cite":"523 U.S. 574","y":1998,"id":"1997/96-827","sc":1,"sum":"The Court held that the Court of Appeals erred in fashioning a heightened burden of proof for unconstitutional-motive cases against public officials. \"Neither the text of [section 1983] or any other federal statute, nor the Federal Rules of Civil Procedure, provides any support for imposing the clear and convincing burden of proof on plaintiffs either at the summary judgment stage or in the trial itself,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Cree v. Washington","cite":"990 F.2d 1256","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/990/1256/","by":{"2":"30"}},{"t":"case","label":"Cree v. Waterbury","cite":"78 F.3d 1400","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/78/1400/","by":{"2":"30"}},{"t":"case","label":"Dandridge v. Williams","cite":"397 U.S. 471","y":1970,"id":"1969/131","sc":1,"sum":"The Court concluded that the Maryland provision violated neither the Social Security Act nor the Equal Protection Clause.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Davis v. County of Westmoreland","cite":"844 A.2d 54","y":2004,"court":"Pa. Commw. Ct.","url":"https://www.courtlistener.com/c/A.2d/844/54/","by":{"2":"42"}},{"t":"case","label":"District of Columbia v. Carter","cite":"409 U.S. 418","y":1973,"id":"1972/71-564","sc":1,"sum":"The District of Columbia is not a \"State or Territory\" within the meaning of 42 U. S. C. § 1983, and the Court of Appeals therefore erred insofar as that court sustained respondent's claims for deprivation of civil rights pursuant to that statute. Pp. 420-433. 144 U. S. App. D. C. 388, 447 F. 2d 358, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"DuBerry v. District of Columbia","cite":"824 F.3d 1046","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/824/1046/","by":{"2":"3, 31"}},{"t":"case","label":"Edye v. Robertson","cite":"112 U.S. 580","y":1884,"id":"scdb/1884-060","sc":1,"sum":"The act of Congress of August 8, 1882, “to regulate immigration,” which imposes upon the owners' of steam or sailing vessels who shall bring passengers from a foreign port into a port of the United States, a duty of fifty cents for every such, passenger not a citizen of this’ country, is a valid exercise of the power to regulate commerce with foreign nations.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"31","3":"10, 11"}},{"t":"case","label":"FCC v. NextWave Pers. Commc’ns Inc.","cite":"537 U.S. 293","y":2003,"id":"2002/01-653","sc":1,"sum":"The Court held that the FCC's cancellations of the licenses violated section 525(a) as revocations of government licenses solely for nonpayment of the debtors' dischargeable debts.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"First Nat. Bank of Omaha v. Marquette Nat. Bank of Minneapolis","cite":"636 F.2d 195","y":1980,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/636/195/","op":7,"ar":5,"by":{"2":"36"}},{"t":"case","label":"Golden State Transit Corp. v. City of Los Angeles","cite":"493 U.S. 103","y":1989,"id":"1989/88-840","sc":1,"op":1,"sum":"Petitioner is entitled to maintain a § 1983 action for compensatory damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40","3":"13, 14"}},{"t":"case","label":"Hague v. Comm. Indus. Org.","cite":"307 U.S. 496","y":1939,"id":"1900-1940/307us496","sc":1,"sum":"The Court held that enforcement of a Jersey City ordinance violated the CIO's right to assembly under the First Amendment as applied to the states by the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"sum":"The Court ruled that the general rule excluding evidence obtained in violation of the Fourth Amendment does not apply to the \"knock-and-announce\" rule.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Jefferson v. Hackney","cite":"406 U.S. 535","y":1972,"id":"1971/70-5064","sc":1,"sum":"Appellants, recipients of Aid to Families With Dependent Children (AFDC), challenge the system whereby Texas, in order to allocate its fixed pool of -welfare money among persons with acknowledged need, applies a percentage reduction factor to arrive at a reduced standard of need, the factor being lower for AFDC than for other categorical assistance programs. Appellants assert that the State's method of applying this …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Jett v. Dallas Indep. Sch. Dist.","cite":"491 U.S. 701","y":1989,"id":"1988/87-2084","sc":1,"sum":"The judgment is affirmed in part, and the cases are remanded. 798 F. 2d 748 and 837 F. 2d 1244, affirmed in part and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts 1, 111, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Knick v. Twp. of Scott","cite":"139 S. Ct. 2162","y":2019,"id":"2018/17-647","sc":1,"op":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"case","label":"Lewis v. Martin","cite":"397 U.S. 552","y":1970,"id":"1969/829","sc":1,"sum":"Appellants, recipients of Aid to Families With Dependent Children (AFDC) assistance, brought this suit challenging the validity of a California law and regulations that conclusively presume that the income of a nonadoptive stepfather or a man assuming therole of a spouse (MARS) is available to the children in computing the AFDC assistance to which they are entitled. Appellants contend that the state provisions …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"McGrath v. Kristensen","cite":"340 U.S. 162","y":1950,"id":"1940-1955/340us162","sc":1,"sum":"The Court affirmed the Court of Appeals and held that Kristensen was not only entitled to challenge his deportation, but that he was eligible for naturalization.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"2":"25, 26"}},{"t":"case","label":"Mitchum v. Foster","cite":"407 U.S. 225","y":1972,"id":"1971/70-27","sc":1,"op":3,"sum":"Title 42 U. S. C.'§ 1983, which authorizes a suit in-equity to redress the deprivation under color of state law \"of any rights, privileges, or immunities secured by theConstitution.. '.,\" is within that exception of the federal anti-injunction statute, 28 U. S. C. § 2283, that provides 'that a federal court may not enjoin state court proceedings \"except as. expressly authorized by Act of Congress.\" And in this § …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4, 5, 40"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"N.Y. Dep’t of Soc. Servs. v. Dublino","cite":"413 U.S. 405","y":1973,"id":"1972/72-792","sc":1,"sum":"The 1967 amendments to the Social Security Act included the Federal Work Incentive Program (WIN), designed to help individuals on welfare become wage-earning members of society. The States were required to incorporate this program into their Aid to Families With Dependent Children (AFDC) program, to provide that certain \"employable\" individuals, as a condition for receiving aid, shall register for manpower services, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Neal v. United States","cite":"516 U.S. 284","y":1996,"id":"1995/94-9088","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court held that Section 841(b)(1) directs a sentencing court to take into account the actual weight of the blotter paper with its absorbed LSD, even though the U. S. Sentencing Commission's Guidelines Manual requires a different method of calculating the weight of an LSD mixture or substance.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Ohio Bureau of Emp. Servs. v. Hodory","cite":"431 U.S. 471","y":1977,"id":"1976/75-1707","sc":1,"sum":"Appellee, an employee of United States Steel Corporation (USS) at a plant in Ohio, was furloughed when the plant was shut down because of a reduction in fuel supply resulting from a nationwide strike of workers at USS's coal mines. Appellee applied to appellant Ohio Bureau of Employment Services for unemployment benefits but his claim was disallowed under an Ohio statute that disqualified a worker from such benefits …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"27, 28"}},{"t":"case","label":"Oklahoma City v. Tuttle","cite":"471 U.S. 808","y":1985,"id":"1984/83-1919","sc":1,"sum":"The Court held that the district court’s instructions to the jury improperly allowed a plaintiff to impose liability on the city without proof of a single action taken by a municipal policy maker.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Patsy v. Bd. of Regents","cite":"457 U.S. 496","y":1982,"id":"1981/80-1874","sc":1,"sum":"Exhaustion of state administrative remedies is not a prerequisite to an action under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 25"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Philbrook v. Glodgett","cite":"421 U.S. 707","y":1975,"id":"1974/73-1820","sc":1,"sum":"Under the Aid to Families with Dependent Children (AFDC) program of the Social Security Act (Act), the term \"dependent child\" was expanded to include children whose deprivation was caused by a parent's unemployment. Section 407 (b) (2) (C) (ii) of the Act, as amended in 1968, makes this expanded definition applicable only if a state plan under the AFDC program denies aid to a dependent child so defined \"with respect …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 23"}},{"t":"case","label":"Pulliam v. Allen","cite":"466 U.S. 522","y":1984,"id":"1983/82-1432","sc":1,"sum":"The Court held that the precedent set by British common law relied on the issuance of writs, rather than the imposition of judicial immunity, to protect judicial independence. The United States never had a doctrine of judicial immunity from prospective relief, and there was no evidence that the lack of that protection created a chilling effect on judicial independence.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22, 23"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Romero v. Kitsap Cnty.","cite":"931 F.2d 624","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/624/","by":{"2":"30"}},{"t":"case","label":"Rosado v. Wyman","cite":"397 U.S. 397","y":1970,"id":"1969/540","sc":1,"sum":"The Social Security Amendments of 1967 added § 402 (a) (23), which reads: \"[The States shall] provide that by July 1, 1969, the amounts used by the State to determine needs of individuals will have been adjusted to reflect fully changes in living costs since such amounts were established and any maximums that the State imposes on the amount of aid paid to families will have been proportionately adjusted.\" In 1969 …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5, 6, 22, 23"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Shea v. Vialpando","cite":"416 U.S. 251","y":1974,"id":"1973/72-1513","sc":1,"sum":"Section 402 (a) (7) of the Social Security Act requires state agencies in administering the Aid to Families with Dependent Children (AFDC) program to \"take into consideration... any expenses reasonably attributable to the earning of... income.\" Such.expenses are deducted from an AFDC applicant's income in determining eligibility for assistance. Colorado's AFDC regulations, which previously had permitted the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 23"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"sum":"The Court held that burning the American Flag is protected free speech under the First Amendment.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affs. v. Inclusive Communities Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"2":"22, 23, 25"}},{"t":"case","label":"TVA v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"sum":"The Supreme Court held that Congress’ continued appropriation of funds did not imply that the Dam project was exempt from the ESA. The operation of the Tellico Dam would wipe out the Snail Darter's habitat, so an injunction was the proper remedy.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"U.S. Nat’l Bank of Or. v. Indep. Ins. Agents of Am., Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"UARG v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"op":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"42"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"31"}},{"t":"case","label":"Yellen v. Confederated Tribes of Chehalis Rsrv.","cite":"141 S. Ct. 2434","y":2021,"id":"2020/20-543","sc":1,"sum":"Alaska Native Corporations are “Indian tribe[s]” under the Indian Self-Determination and Education Assistance Act and thus eligible for funding available to “Tribal governments” under Title V of the Coronavirus Aid, Relief, and Economic Security Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"27"}},{"t":"usc","label":"18 U.S.C. § 926C","url":"https://www.law.cornell.edu/uscode/text/18/926C","by":{"2":"3, 31"}},{"t":"usc","label":"20 U.S.C. § 1232g","url":"https://www.law.cornell.edu/uscode/text/20/1232g","subs":["(f)"],"by":{"2":"12, 13"}},{"t":"usc","label":"42 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/42/1301","by":{"2":"11, 22"}},{"t":"usc","label":"42 U.S.C. § 1437a","url":"https://www.law.cornell.edu/uscode/text/42/1437a","by":{"2":"10"}},{"t":"usc","label":"42 U.S.C. § 1997a","url":"https://www.law.cornell.edu/uscode/text/42/1997a","subs":["(a)"],"stext":{"head":"§1997a. Initiation of civil actions","paras":[[0,"(a) Discretionary authority of Attorney General; preconditions"],[0,"Whenever the Attorney General has reasonable cause to believe that any State or political subdivision of a State, official, employee, or agent thereof, or other person acting on behalf of a State or political subdivision of a State is subjecting persons residing in or confined to an institution, as defined in section 1997 of this title, to egregious or flagrant conditions which deprive such persons of any rights, privileges, or immunities secured or protected by the Constitution or laws of the United States causing such persons to suffer grievous harm, and that such deprivation is pursuant to a pattern or practice of resistance to the full enjoyment of such rights, privileges, or immunities, the Attorney General, for or in the name of the United States, may institute a civil action in any appropriate United States district court against such party for such equitable relief as may be appropriate to insure the minimum corrective measures necessary to insure the full enjoyment of such rights, privileges, or immunities, except that such equitable relief shall be available under this subchapter to persons residing in or confined to an institution as defined in section 1997(1)(B)(ii) of this title only insofar as such persons are subjected to conditions which deprive them of rights, privileges, or immunities secured or protected by the Constitution of the United States."],[0,"(b) Discretionary award of attorney fees"],[0,"In any action commenced under this section, the court may allow the prevailing party, other than the United States, a reasonable attorney's fee against the United States as part of the costs."],[0,"(c) Attorney General to personally sign complaint"],[0,"The Attorney General shall personally sign any complaint filed pursuant to this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997a?type=usc&year=mostrecent&link-type=html"},"head":"§1997a. Initiation of civil actions","tname":"The Public Health and Welfare","by":{"2":"7, 8, 7","3":"14"}},{"t":"usc","label":"42 U.S.C. § 6010","url":"https://www.law.cornell.edu/uscode/text/42/6010","ar":1,"tname":"The Public Health and Welfare","by":{"2":"9, 10"}},{"t":"law","label":"Federal Courts Improvement Act, Pub. L. No. 104-317","url":"https://www.govinfo.gov/link/plaw/104/public/317","by":{"2":"11"}},{"t":"law","label":"Pub. L. No. 96-170","url":"https://www.govinfo.gov/link/statute/93/1284","by":{"2":"6"}},{"t":"reg","label":"42 C.F.R. § 431.231","url":"https://www.ecfr.gov/current/title-42/section-431.231","by":{"2":"40"}},{"t":"reg","label":"42 C.F.R. § 483.12","url":"https://www.ecfr.gov/current/title-42/section-483.12","subs":["(c)"],"by":{"2":"40"}},{"t":"reg","label":"39 Fed. Reg. 15230","url":"https://www.govinfo.gov/link/fr/39/15230","by":{"2":"15"}},{"t":"reg","label":"39 Fed. Reg. 35774","url":"https://www.govinfo.gov/link/fr/39/35774","by":{"2":"15"}},{"t":"reg","label":"46 Fed. Reg. 7408","url":"https://www.govinfo.gov/link/fr/46/7408","by":{"2":"15"}},{"t":"case","label":"Allen v. Thomas","cite":"60 Ky. 198","y":1860,"url":"https://www.courtlistener.com/c/Ky./60/198/","sum":"Upholding right of intended beneficiary to enforce agreement by defendant to pass along funds to plaintiff.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"case","label":"Arlington Cent. Sch. Dist. Bd. of Educ. v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"ar":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that IDEA did not authorize reimbursement of expert fees. \"While authorizing the award of reasonable attorney's fees, the Act contains detailed provisions that are designed to ensure that such awards are indeed reasonable,\" Justice Alito wrote. \"The absence of any comparable provisions relating to expert fees strongly suggests that recovery of expert fees is not authorized.\" Justice Alito went on to write that the case was made even simpler by the fact that, as an exercise of Congress's Spending Clause power, any provision requiring reimbursement of expert fees would have had to be \"unambiguous,\" which it clearly was not.","sumSrc":"Oyez","by":{"3":"2"}},{"t":"case","label":"Astra USA, Inc. v. Santa Clara Cnty.","cite":"563 U.S. 110","y":2011,"id":"2010/09-1273","sc":1,"sum":"The Court held that health care providers cannot sue drug makers for overcharging public hospitals for prescription drugs.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Barnes v. Gorman","cite":"536 U.S. 181","y":2002,"id":"2001/01-682","sc":1,"op":13,"ar":1,"sum":"The Court held that, because punitive damages may not be awarded in private suits brought under Title VI of the 1964 Civil Rights Act, it follows that they may not be awarded in suits brought under the ADA and the Rehabilitation Act.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Bohanan v. Pope","cite":"42 Me. 93","y":1856,"url":"https://www.courtlistener.com/c/Me./42/93/","by":{"3":"7"}},{"t":"case","label":"Brewer v. Dyer","cite":"61 Mass. 337","y":1851,"url":"https://www.courtlistener.com/c/Mass./61/337/","by":{"3":"7"}},{"t":"case","label":"Bristow v. Lane","cite":"21 Ill. 194","y":1859,"url":"https://www.courtlistener.com/c/Ill./21/194/","sum":"Upholding right of intended beneficiary to enforce agreement by defendant to pass along funds to plaintiff.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"case","label":"Comm. of U.S. Citizens Living in Nicar. v. Reagan","cite":"859 F.2d 929","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/859/929/","by":{"3":"11"}},{"t":"case","label":"Foster v. Lookout Water Co.","cite":"71 Tenn. 42","y":1879,"url":"https://www.courtlistener.com/c/Tenn./71/42/","by":{"3":"9"}},{"t":"case","label":"Franklin v. Gwinnett Cnty. Pub. Schs.","cite":"503 U.S. 60","y":1992,"id":"1991/90-918","sc":1,"sum":"Justice Byron R. White wrote the Court's unanimous decision, holding that monetary damages are available under Title IX because there is a presumption that any appropriate relief is available to remedy the violation of a federal right. In this case, back pay and prospective relief were not sufficient remedies.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Frolova v. U.S.S.R.","cite":"761 F.2d 370","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/761/370/","by":{"3":"11"}},{"t":"case","label":"Haitian Refugee Ctr. v. Baker","cite":"949 F.2d 1109","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/949/1109/","by":{"3":"11"}},{"t":"case","label":"Hind v. Holdship","cite":"2 Watts 104","y":1833,"court":"Pa.","url":"https://www.courtlistener.com/c/Watts/2/104/","by":{"3":"7"}},{"t":"case","label":"Morgan v. Overman Silver Mining Co.","cite":"37 Cal. 534","y":1869,"url":"https://www.courtlistener.com/c/Cal./37/534/","sum":"Upholding right of creditor to “recover the debt” that defendant agreed to pay as consideration for property acquisition.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"case","label":"Nickerson v. Bridgeport Hydraulic Co.","cite":"46 Conn. 24","y":1878,"url":"https://www.courtlistener.com/c/Conn./46/24/","by":{"3":"9"}},{"t":"const","label":"Article I, Section 8","by":{"3":"2"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"3":"2"}},{"t":"usc","label":"42 U.S.C. § 2000d-7","url":"https://www.law.cornell.edu/uscode/text/42/2000d-7","subs":["(a)(2)"],"by":{"3":"14"}}]};